import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sdpa_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
